// McpGrant domain model and enforcement.
//
// The grant is the authoritative permission record for an MCP user + OAuth
// client. It is resolved from CommonCal core (the source of truth) through the
// internal API and converted into this domain type. Permission checks operate
// on the in-memory grant; there is no MCP-local grant table.

use serde::{Deserialize, Serialize};

use crate::internal_client::McpGrantResponse;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct McpGrant {
    pub grant_id: String,
    pub user_id: i64,
    pub oauth_client_id: String,
    pub allowed_calendar_ids: Vec<i64>,
    pub allow_availability: bool,
    pub allow_event_titles: bool,
    pub allow_event_details: bool,
    pub allow_create: bool,
    pub allow_update: bool,
    pub allow_delete: bool,
    pub created_at: i64,
    pub last_used_at: Option<i64>,
    pub expires_at: Option<i64>,
    pub revoked_at: Option<i64>,
}

/// Convert an authoritative core grant response into the domain type.
impl From<McpGrantResponse> for McpGrant {
    fn from(response: McpGrantResponse) -> Self {
        Self {
            grant_id: response.grant_id,
            user_id: response.user_id,
            oauth_client_id: response.oauth_client_id,
            allowed_calendar_ids: response.allowed_calendar_ids,
            allow_availability: response.allow_availability,
            allow_event_titles: response.allow_event_titles,
            allow_event_details: response.allow_event_details,
            allow_create: response.allow_create,
            allow_update: response.allow_update,
            allow_delete: response.allow_delete,
            created_at: response.created_at,
            last_used_at: response.last_used_at,
            expires_at: response.expires_at,
            revoked_at: response.revoked_at,
        }
    }
}

/// Check if a calendar is accessible under the grant.
///
/// Returns true if:
/// - Grant is not revoked
/// - Grant is not expired (if expires_at is set)
/// - Calendar ID is in the allowed list
pub fn check_calendar_access(grant: &McpGrant, calendar_id: i64) -> bool {
    if grant.revoked_at.is_some() {
        return false;
    }
    if let Some(expires_at) = grant.expires_at
        && current_time_secs() > expires_at
    {
        return false;
    }
    grant.allowed_calendar_ids.contains(&calendar_id)
}

/// Check if a tool is permitted under the grant.
///
/// Returns true if:
/// - Grant is not revoked
/// - Grant is not expired
/// - The tool name maps to a permission the grant allows
pub fn check_tool_permission(grant: &McpGrant, tool_name: &str) -> bool {
    if grant.revoked_at.is_some() {
        return false;
    }
    if let Some(expires_at) = grant.expires_at
        && current_time_secs() > expires_at
    {
        return false;
    }
    match tool_name {
        "availability_find" | "availability_get" => grant.allow_availability,
        // calendar_list is a calendar-metadata read; it is gated by the
        // availability/metadata capability, distinct from the availability_find
        // tool capability.
        "calendar_list" => grant.allow_availability,
        "event_get" | "event_search" => grant.allow_event_titles,
        "event_create" => grant.allow_create,
        "event_update" => grant.allow_update,
        "event_delete_prepare" | "event_delete_commit" => grant.allow_delete,
        "reminder_set" => grant.allow_create,
        _ => false,
    }
}

/// Get current time as Unix seconds.
///
/// In production this uses system time. For testing, set MCP_TEST_TIME
/// to a fixed timestamp.
pub fn current_time_secs() -> i64 {
    if let Ok(test_time) = std::env::var("MCP_TEST_TIME") {
        return test_time
            .parse()
            .unwrap_or_else(|_| current_time_secs_real());
    }
    current_time_secs_real()
}

fn current_time_secs_real() -> i64 {
    std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or_else(|_| 0)
}

